mapper.select:
SELECT ppa.DEPOSIT_ATTACHMENT_ID, ppa.MANAGE_HD_ID, ppa.DOCUMENT_NAME, ppa.DESCRIPTION, ( SELECT wm_concat( fa.file_name ) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'csh_deposit_attachment' AND ppa.DEPOSIT_ATTACHMENT_ID = fam.table_pk_value ) file_name, ( SELECT max( fat.last_update_date ) FROM fnd_atm_attachment fat, fnd_atm_attachment_multi faam WHERE fat.attachment_id = faam.attachment_id AND faam.table_name = 'csh_deposit_attachment' AND faam.table_pk_value = ppa.DEPOSIT_ATTACHMENT_ID ) upload_date, ( SELECT max( su.description ) FROM sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam WHERE fat.attachment_id = faam.attachment_id AND faam.table_name = 'csh_deposit_attachment' AND faam.table_pk_value = ppa.DEPOSIT_ATTACHMENT_ID AND su.user_id = fat.last_updated_by ) upload_person,
(select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'csh_deposit_attachment' and faam.table_pk_value = ppa.DEPOSIT_ATTACHMENT_ID and faa.source_pk_value = faam.record_id) attachment_id FROM csh_deposit_attachment ppa
and ppa.deposit_attachment_id = #{depositAttachmentId}
and ppa.manage_hd_id = #{manageHdId}

SELECT ppa.DEPOSIT_ATTACHMENT_ID, ppa.MANAGE_HD_ID, ppa.DOCUMENT_NAME, ppa.DESCRIPTION, ( SELECT wm_concat( fa.file_name ) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'csh_deposit_attachment' AND ppa.DEPOSIT_ATTACHMENT_ID = fam.table_pk_value ) file_name, ( SELECT max( fat.last_update_date ) FROM fnd_atm_attachment fat, fnd_atm_attachment_multi faam WHERE fat.attachment_id = faam.attachment_id AND faam.table_name = 'csh_deposit_attachment' AND faam.table_pk_value = ppa.DEPOSIT_ATTACHMENT_ID ) upload_date, ( SELECT max( su.description ) FROM sys_user su, fnd_atm_attachment fat, fnd_atm_attachment_multi faam WHERE fat.attachment_id = faam.attachment_id AND faam.table_name = 'csh_deposit_attachment' AND faam.table_pk_value = ppa.DEPOSIT_ATTACHMENT_ID AND su.user_id = fat.last_updated_by ) upload_person,
(select max(faa.attachment_id) from fnd_atm_attachment faa, fnd_atm_attachment_multi faam where faam.table_name = 'csh_deposit_attachment' and faam.table_pk_value = ppa.DEPOSIT_ATTACHMENT_ID and faa.source_pk_value = faam.record_id) attachment_id FROM csh_deposit_attachment ppa
and ppa.deposit_attachment_id = #{depositAttachmentId}
